import config from '@/config/logger'

const logger = (level, message) => {
  const loggerConfig = config.styles.filter(item => item.level === level)
  const outputMessage = message.toString()

  return config.styled
    ? config.log[`${level}`](
        `%c${outputMessage}`,
        `color: ${loggerConfig[0].color}`
      )
    : config.log[`${level}`](outputMessage)
}

export default logger
