import log from 'electron-log'

import { appReference, logToFile, logToConsole } from '@/config/env'

const config = {
  styled: true,
  styles: [
    { level: 'info', color: 'green' },
    { level: 'warn', color: '' },
    { level: 'error', color: 'red' },
    { level: 'debug', color: 'cyan' },
  ],
  format: '[{y}-{m}-{d} {h}:{i}:{s}.{ms}] [{appName}] [{level}] {text}',
  fileName: 'ttpc',
}

log.variables.appName = `${appReference}-${
  log.variables.processType === 'browser' ? 'main' : 'renderer'
}`
log.transports.file.level = Boolean(logToFile)
log.transports.file.format = config.format
log.transports.file.fileName = `${config.fileName}.log`
log.transports.console.useStyles = Boolean(config.styled)
log.transports.console.level = Boolean(logToConsole)
log.transports.console.format = config.format

export default {
  ...config,
  log,
}
