<template>
  <div class="container-video">
    <div class="menu-video">
      <div class="drag-zone" />
      <button class="btn-minimize" @click="minimize()" :disabled="loading">
        <img :src="require('../../assets/scale-window.svg')" />
      </button>
      <button class="btn-close" @click="close()" :disabled="loading">
        <img :src="require('../../assets/close-window.svg')" />
      </button>
    </div>
    <div class="video-section">
      <iframe
        v-if="video"
        :src="
          `https://www.youtube-nocookie.com/embed/${video.videoId}?fs=0&autoplay=1&rel=0`
        "
        :title="video.title"
        frameborder="0"
        allowfullscreen
      />
    </div>
  </div>
</template>

<script>
import VIDEO_WINDOW_EVENTS from '@/config/events/videoWindow'

import rendererEventsService from '@/services/renderer/rendererEvents'

export default {
  name: 'VideoPlayer',
  data() {
    return {
      video: null,
      isMinimize: false,
      loading: true,
    }
  },
  methods: {
    getVideo() {
      rendererEventsService.subscribe('send-video', (event, data) => {
        this.video = data.video
        this.loading = false
      })
    },
    minimize() {
      rendererEventsService.send(VIDEO_WINDOW_EVENTS.channel, {
        event: VIDEO_WINDOW_EVENTS.events.minimize.name,
        data: this.isMinimize,
      })
      this.isMinimize = !this.isMinimize
    },
    close() {
      rendererEventsService.send(VIDEO_WINDOW_EVENTS.channel, {
        event: VIDEO_WINDOW_EVENTS.events.close.name,
      })
    },
  },
  created() {
    this.getVideo()
  },
}
</script>

<style lang="scss">
html,
body {
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
}

.container-video {
  height: 100%;
  min-height: 100%;
  display: flex;
  flex-direction: column;
}

.menu-video {
  height: 30px;
  display: flex;

  .drag-zone {
    flex: 1;
    cursor: move;
    background: #efefef;
    -webkit-app-region: drag;
  }

  button {
    border: none;
    padding: 0 0.85em;
    font-size: 16px;
    cursor: pointer !important;
    background: #efefef;
  }
}
.btn-minimize:hover {
  background: #b1b1b1;
}
.btn-close:hover {
  background: #ff6347;
}

.video-section {
  flex: 1;

  iframe {
    height: 100%;
    width: 100%;
  }
}
</style>
